function createTwoLineProgressBars(frm) {
    const INACTIVE = '#b7b6b6';
    const GREEN = '#28a745';
    const isSubmitted = frm.doc.docstatus >= 1;

    const flows = [];

    const hasStoneSO = (frm.doc.custom_bom_items || []).some(item => !!item.custom_sales_order_id);
    const hasSOName = !frm.doc.__islocal;

    if (frm.doc.custom_sales_order_type === "Stone") {
        // Sirf Stone wali bar
        flows.push({
            label: 'Stone',
            steps: ['Sales Order', 'Stone Request', 'Purchase Invoice', 'Sales Invoice'].map(step =>
                step === 'Stone Request' ? step : `Stone ${step}`
            ),
            itemType: 'Stone',
            color: '#4eb9e4'
        });
    } else {
        // SKU wali bar
        flows.push({
            label: 'SKU',
            steps: ['Sales Order', 'Purchase Order', 'Purchase Invoice', 'Sales Invoice'].map(step => `SKU ${step}`),
            itemType: 'SKU',
            color: hasSOName ? '#ffa509' : '#d3d3d3'
        });

        // Stone wali bar (optional)
        flows.push({
            label: 'Stone',
            steps: ['Sales Order', 'Stone Request', 'Purchase Invoice', 'Sales Invoice'].map(step =>
                step === 'Stone Request' ? step : `Stone ${step}`
            ),
            itemType: 'Stone',
            color: hasStoneSO ? '#4eb9e4' : '#d3d3d3'
        });
    }

    const getStatus = (itemType) => getCurrentStep(frm, itemType);

    let html = `<div style="width:100%;max-width:1000px;margin:0px;">`;

    flows.forEach(flow => {
        const currStep = getStatus(flow.itemType);
        const STEP_COLOR = isSubmitted ? GREEN : flow.color;
        const badgeColor = flow.color;

        html += `<div style="display:flex;align-items:center;margin-bottom:14px;">`;

        html += `<div style="width:72px;font-size:13px;border-radius: 10px;background: ${badgeColor};color:white;font-weight:600;text-align:center;margin-right:24px;">${flow.label}:</div>`;

        html += `<div style="flex:1;display:flex;align-items:center;">`;

        flow.steps.forEach((step, i) => {
            const isActive = i <= currStep;

            // 👇 filters for each step
            const {doctype, filters} = getLinkedFilter(step, frm);

            html += `
                <div 
                    onclick='frappe.set_route("List", "${doctype}", ${JSON.stringify(filters)})' 
                    style="cursor: pointer; font-size:15px;font-weight:${isActive ? 500 : 400};
                           color:${isActive ? STEP_COLOR : INACTIVE};
                           margin-top:2px;white-space:nowrap;text-decoration:underline;"
                >
                    ${step}
                </div>
            `;

            if (i < flow.steps.length - 1) {
                html += `
                    <div style="height: 2.5px;width: 100px;flex:1;background:${i < currStep ? STEP_COLOR : INACTIVE};
                                margin-bottom:0px;margin-left:10px;margin-right:10px;z-index:1;
                                border-radius:3px;position:relative;">
                        <div style="
                            position: absolute;
                            right: -6px;
                            top: -6px;
                            width: 0;
                            height: 0;
                            border-top: 7px solid transparent;
                            border-bottom: 7px solid transparent;
                            border-left: 7px solid ${i < currStep ? STEP_COLOR : INACTIVE};
                        "></div>
                    </div>
                `;
            }
        });

        html += `</div></div>`;
    });

    html += `</div>`;
    return html;
}


function show_progress_bar(frm) {
    if (!frm.fields_dict.custom_progress_status) return;

    const finalHTML = createTwoLineProgressBars(frm);
    frm.fields_dict.custom_progress_status.$wrapper.html(finalHTML);
}

function update_custom_item_details(frm) {
    let first_item = (frm.doc.items && frm.doc.items.length > 0) ? frm.doc.items[0] : null;
    
    if (!first_item) {
        frm.fields_dict.custom_item_details.$wrapper.html("<p style='color:#888;'>No items found</p>");
        return;
    }

    if (first_item.item_code) {
        frappe.db.get_value('Item', first_item.item_code, ['image', 'item_name', 'custom_customer_sku'], (r) => {
            let image_url = r.image || "";
            let vendor_product_id = first_item.custom_vendor_product_id || "";
            let customer_sku_from_item = r.custom_customer_sku || "";
            let customer_sku = customer_sku_from_item || first_item.custom_customer_sku || "";
            let main_stone = frm.doc.custom_main_stone || "";

            let image_html = "";
            if (image_url) {
                image_html = `<img src="${image_url}" style="max-width: 150px; max-height: 120px; object-fit: contain; border-radius: 8px;" alt="Item Image">`;
            }

            let vendor_id_html = vendor_product_id ? `<p style="margin: 5px 0;"><strong>Vendor Product ID:</strong> ${vendor_product_id}</p>` : "";
            let sku_html = customer_sku ? `<p style="margin: 5px 0;"><strong>Customer SKU:</strong> ${customer_sku}</p>` : "";
            let stone_html = main_stone ? `<p style="margin: 5px 0;"><strong>Main Stone:</strong> ${main_stone}</p>` : "";

            let html_content = `
                <div style="">
                    <div style="flex-shrink: 0; width: 150px; display: flex; justify-content: center; align-items: center;">
                        ${image_html || `<div style="width: 150px; height: 120px; background-color: #f0f0f0; display: flex; align-items: center; justify-content: center; border-radius: 8px; border: 2px dashed #ccc;"><span style="color: #888; font-size: 14px;">No Image</span></div>`}
                    </div>
                    <div style="flex: 1; min-width: 0;">
                        <div style="color: #666; font-size: 14px;">
                            ${vendor_id_html}
                            ${sku_html}
                            ${stone_html}
                            ${!vendor_product_id && !customer_sku && !main_stone ? '<p style="color: #888; font-style: italic;">No additional details available</p>' : ''}
                        </div>
                    </div>
                </div>
            `;

            frm.fields_dict.custom_item_details.$wrapper.html(html_content);
        });
    } else {
        frm.fields_dict.custom_item_details.$wrapper.html("<p style='color:#888;'>No item code found</p>");
    }
}

