    },
    items_on_form_rendered: function (frm) {
        update_custom_item_details(frm);
    }
});

function getLinkedDoctype(step) {
    let cleaned_step = step;
    if (!['Stone Request'].includes(step)) {
        cleaned_step = step.replace(/^SKU |^Stone /, '');
    }

    const map = {
        'Sales Order': 'Sales Order',
        'Purchase Order': 'Purchase Order',
        'Purchase Invoice': 'Purchase Invoice',
        'Sales Invoice': 'Sales Invoice',
        'Stone Request': 'Stone Request'
    };

    return map[cleaned_step] || '';
}




function update_custom_item_details(frm) {
    let first_item = (frm.doc.items && frm.doc.items.length > 0) ? frm.doc.items[0] : null;
    
    if (!first_item) {
        frm.fields_dict.custom_item_details.$wrapper.html("<p style='color:#888;'>No items found</p>");
        return;
    }

    let image_html = '';
    
    if (first_item.image_view) {
        image_html = first_item.image_view;
    }
    else if (first_item.image) {
        image_html = `<img src="${first_item.image}" style="max-width: 150px; max-height: 100px; object-fit: contain;" alt="Item Image">`;
    }
    else if (first_item.item_code) {
        frappe.db.get_value('Item', first_item.item_code, 'image', (r) => {
            if (r.image) {
                image_html = `<img src="${r.image}" style="max-width: 150px; max-height: 130px; object-fit: contain;" alt="Item Image">`;
                render_html();
            }
        });
    }

    function render_html() {
        let vendor_product_id = first_item.custom_vendor_product_id || "";
        let customer_sku = first_item.custom_customer_sku || "";
        let main_stone = frm.doc.custom_main_stone || "";

        let vendor_id_html = vendor_product_id ? `<p><b>Vendor Product ID:</b> ${vendor_product_id}</p>` : "";
        let sku_html = customer_sku ? `<p><b>Customer SKU:</b> ${customer_sku}</p>` : "";
        let stone_html = main_stone ? `<p><b>Main Stone:</b> ${main_stone}</p>` : "";

        let html_content = `
            <div style="">
                ${image_html ? `<div style="flex-shrink: 0;">${image_html}</div>` : `<div style="flex-shrink: 0; width: 150px; height: 100px; background-color: #e9ecef; display: flex; align-items: center; justify-content: center; border-radius: 3px; border: 2px dashed #dee2e6;"><span style="color: #6c757d;">No Image</span></div>`}
                <div style="flex: 1;">
                    <h6 style="margin: 0 0 10px 0; color: #333;">${first_item.item_name || first_item.item_code || 'Item Details'}</h6>
                    ${vendor_id_html}
                    ${sku_html}
                    ${stone_html}
                </div>
            </div>
        `;

