function getLinkedFilter(step, frm) {
    let doctype = "";
    let filters = {};

    if (step.includes("Purchase Order")) {
        doctype = "Purchase Order";
        const po_ids = (frm.doc.items || [])
            .map(i => i.custom_purchase_order_no)
            .filter(Boolean);
        if (po_ids.length) {
            filters = { name: ["in", po_ids] };
        }

    } else if (step.includes("Stone Request")) {
        doctype = "Stone Request";
        const sr_ids = (frm.doc.custom_bom_items || [])
            .map(i => i.custom_stone_request_id)
            .filter(Boolean);
        if (sr_ids.length) {
            filters = { name: ["in", sr_ids] };
        }

    } else if (step.includes("Sales Order") && step.includes("Stone")) {
        doctype = "Sales Order";
        const so_ids = (frm.doc.custom_bom_items || [])
            .map(i => i.custom_sales_order_id)
            .filter(Boolean);
        if (so_ids.length) {
            filters = { name: ["in", so_ids] };
        }

    } else if (step.includes("Sales Order")) {
        // normal SO khud hi
        doctype = "Sales Order";
        filters = { name: frm.doc.name };

    } else if (step.includes("Purchase Invoice")) {
        doctype = "Purchase Invoice";
        filters = { sales_order: frm.doc.name };

    } else if (step.includes("Sales Invoice")) {
        doctype = "Sales Invoice";
        filters = { sales_order: frm.doc.name };
    }

    return { doctype, filters };
}

