frappe.ui.form.on('Purchase Order', {
    validate: function(frm) {
        calculate_all_differences(frm);
        const total_buying = flt(frm.doc.custom_total_buying_amt);
        const total_selling = flt(frm.doc.custom_total_selling_amt);

        if (total_buying > total_selling) {
            const has_accounts_manager_role = frappe.user.has_role('Accounts Manager');

            if (!has_accounts_manager_role) {
                frappe.throw(__('Total Buying Amount cannot exceed Total Selling Amount. Please contact Accounts Manager to submit this document.'));
            }
        }    
    },
        custom_bom_items_on_form_rendered: function(frm) {
