        frm.fields_dict['custom_bom_items'].grid.wrapper.on('change', function () {
            frm.trigger('calculate_totals');
        });
    },

    // Call this on field changes if needed
    calculate_totals: function(frm) {
        let total_buying = 0;
        let total_selling = 0;

        frm.doc.custom_bom_items.forEach(row => {
            total_buying += flt(row.rate);
            total_selling += flt(row.selling_rate);
        });

