                frm.refresh_field('customer_bom_items');
            }
        });
    },

    show_all: function(frm) {
        if (!frm.doc.show_all) {
            frm.clear_table('customer_bom_items');
            frm.set_value('bom_id', null);
            frm.refresh_field('customer_bom_items');
            return;
        }
        frm.clear_table('customer_bom_items');
        const uniqueItemCodes = [...new Set((frm.doc.customer_worksheet_items || []).map(row => row.item_code))];
        const bomFetchPromises = uniqueItemCodes.map(item_code =>
            frappe.call({
                method: 'frappe.client.get_list',
                args: {
                    doctype: 'BOM',
                    filters: { item: item_code, is_active: 1, is_default: 1 },
                    limit_page_length: 1,
                    order_by: 'creation desc'
                }
            })
        );
        Promise.all(bomFetchPromises).then(results => {
            const bomCalls = [];
            results.forEach(bomList => {
                if (bomList.message && bomList.message.length > 0) {
                    const bomName = bomList.message[0].name;
                    bomCalls.push(
                        frappe.call({
                            method: 'frappe.client.get',
                            args: { doctype: 'BOM', name: bomName }
                        })
                    );
                }
            });
            Promise.all(bomCalls).then(bomResults => {
                const addedItems = new Set();
                bomResults.forEach(res => {
                    if (res.message && res.message.items) {
                        res.message.items.forEach(item => {
                            const uniqueKey = `${res.message.name}::${item.item_code}`;
                            if (addedItems.has(uniqueKey)) return;

                            let row = frm.add_child('customer_bom_items');
                            Object.assign(row, {
                                item_code: item.item_code,
                                item_name: item.item_name,
                                custom_item_group: item.custom_item_group,
                                bom_no: res.message.name,
                                custom_our_responsibility: item.custom_our_responsibility,
                                qty: item.qty,
                                uom: item.uom,
                                rate: item.rate,
                                amount: item.amount || 0,
                                custom_selling_rate: item.custom_selling_rate || 0,
                                custom_selling_amount: item.custom_selling_amount || 0,
                                custom_gemstone: item.custom_gemstone,
                                custom_stone_treatment_list: item.custom_stone_treatment_list,
                                custom_merch_color__attribute: item.custom_merch_color__attribute,
                                custom_country_of_origin: item.custom_country_of_origin,
                                custom_avg_carat_weight: item.custom_avg_carat_weight,
                                custom_sku_weight: item.custom_sku_weight,
                                custom_grade: item.custom_grade,
                                custom_cut: item.custom_cut,
                                custom_setting_type: item.custom_setting_type,
                                custom_stone_pieces: item.custom_stone_pieces,
                                custom_metal_weight: item.custom_metal_weight,
                                custom_sku_metal_weight: item.custom_sku_metal_weight,
                                custom_metal_group: item.custom_metal_group,
                                description: item.description,
                                custom_with_jback: item.custom_with_jback
                            });
                            addedItems.add(uniqueKey);
                        });
                    }
                });
                frm.refresh_field('customer_bom_items');
            });
        });
    },

    // Description related triggers (merged in one)
    item_name: update_description,
    item_group: update_description,
    gst_hsn_code: update_description,
    brand: update_description,
    custom_customer_sku: update_description,
