// Utility: Clear table(s) and refresh
function clear_and_refresh(frm, tables) {
    (Array.isArray(tables) ? tables : [tables]).forEach(table => {
        frm.clear_table(table);
        frm.refresh_field(table);
    });
}

// Utility: Update each child of a table, optionally restrict to selected
function update_child_table(frm, table, updateFn, onlySelected = false) {
    const grid = frm.fields_dict[table].grid;
    const rows = onlySelected ? grid.get_selected_children() : frm.doc[table] || [];
    if (rows.length) {
        rows.forEach(updateFn);
        frm.refresh_field(table);
    }
}

// Utility: Show or remove the "Create Sales Order" button
function toggle_create_so_button(frm) {
    const items = frm.doc.customer_worksheet_items || [];
    const all_have_sales_orders = items.length > 0 && items.every(row => !!row.sales_order_no);
    frm.remove_custom_button('Create Sales Order');
    if (!all_have_sales_orders) {
        frm.add_custom_button('Create Sales Order', () => handle_sales_order_creation(frm));
    }
}

// Main form events
frappe.ui.form.on('Customer Worksheet', {
    refresh(frm) {
        toggle_create_so_button(frm);
        clear_and_refresh(frm, 'customer_bom_items');
    },

    insert_vendor(frm) {
        const { factory_vendor, delivery_date, order_type } = frm.doc;
        if (!factory_vendor && !order_type && !delivery_date) {
            return frappe.msgprint(__('Please fill at least one of: Factory Vendor, Order Type, or Delivery Date.'));
        }
        update_child_table(frm, 'customer_bom_items', row => {
            if (factory_vendor) row.custom_supplier = factory_vendor;
        });
        update_child_table(frm, 'customer_worksheet_items', row => {
            if (delivery_date) row.eta = delivery_date;
            if (order_type) row.order_type = order_type;
        });
    },

    clear_values(frm) {
        frm.set_value({
            factory_vendor: null,
            order_type: null,
            delivery_date: null
        });
        update_child_table(frm, 'customer_bom_items', row => row.custom_supplier = null);
        update_child_table(frm, 'customer_worksheet_items', row => {
            row.order_type = null;
            row.eta = null;
        });
    },

    fetch_item_with_bom(frm) {
        const items = (frm.doc.customer_worksheet_items || []).filter(r => !r.default_bom);
        // Remove dups by item_code:
        const unique = [];
        const codes = new Set();
        items.forEach(row => {
            if (!codes.has(row.item_code)) {
                unique.push(row);
                codes.add(row.item_code);
            }
        });
        if (unique.length === 0) return frappe.msgprint("All items already have a BOM set in 'Default BOM'.");
        if (unique.length === 1) {
            frm.set_value("finished_goods_item", unique[0].item_code);
            return;
        }
        // Dialog - Only one check can be selected
        const fields = unique.map((item, i) => ({
            fieldname: `item_${i}`,
            label: `${item.item_code} : ${item.item_name}`,
            fieldtype: 'Check',
            default: 0
        }));
        const dialog = new frappe.ui.Dialog({
            title: "Select One Item (No BOM)",
            fields,
            primary_action_label: "Insert to Finished Goods",
            primary_action(values) {
                const selected = unique.find((item, i) => values[`item_${i}`]);
                frm.set_value("finished_goods_item", selected ? selected.item_code : null);
                dialog.hide();
                if (!selected) frappe.msgprint("No item selected.");
            }
        });
        dialog.show();
        setTimeout(() => {
            unique.forEach((item, i) => {
                const $field = dialog.fields_dict[`item_${i}`].$wrapper.find('input[type="checkbox"]');
                $field.on('change', function () {
                    if ($(this).is(':checked')) {
                        unique.forEach((_, j) => {
                            if (j !== i) dialog.fields_dict[`item_${j}`].set_value(0);
                        });
                    }
                });
            });
        }, 100);
    },

    async update_bom_changes(frm) {
        const bom_id = frm.doc.bom_id;
        if (!bom_id) return frappe.msgprint("Please select an existing BOM to update.");

        try {
            const { message: bom_doc } = await frappe.call({
                method: "frappe.client.get",
                args: { doctype: "BOM", name: bom_id }
            });
            if (bom_doc.docstatus === 1) {
                return frappe.msgprint({
                    title: "BOM is Submitted",
                    message: "This BOM is submitted and cannot be updated. Please create a new BOM.",
                    indicator: "red"
                });
            }
            // Copy items
            bom_doc.items = (frm.doc.customer_bom_items || []).map(row => ({
                item_code: row.item_code,
                item_name: row.item_name,
                qty: row.qty || 1,
                uom: row.uom,
                rate: row.rate || 0,
                amount: row.amount || 0,
                description: row.description,
                custom_item_group: row.custom_item_group || '',
                custom_selling_amount: row.custom_selling_amount || '',
                custom_gemstone: row.custom_gemstone,
                custom_stone_treatment_list: row.custom_stone_treatment_list,
                custom_merch_color__attribute: row.custom_merch_color__attribute,
                custom_country_of_origin: row.custom_country_of_origin,
                custom_grade: row.custom_grade,
                custom_stone_pieces: row.custom_stone_pieces,
                custom_avg_carat_weight: row.custom_avg_carat_weight,
                custom_sku_carat_weight: row.custom_sku_carat_weight,
                custom_cut: row.custom_cut,
                custom_setting_type: row.custom_setting_type,
                custom_metal_weight: row.custom_metal_weight,
                custom_sku_metal_weight: row.custom_sku_metal_weight,
                custom_metal_group: row.custom_metal_group,
                custom_selling_rate: row.custom_selling_rate,
                custom_sku_weight: row.custom_sku_weight,
                custom_ext_qty_required: row.custom_ext_qty_required,
                custom_oh: row.custom_oh,
                custom_net_balance_required: row.custom_net_balance_required,
                custom_our_responsibility: row.custom_our_responsibility,
                custom_bom_id: row.bom_no,
                custom_with_jback: row.custom_with_jback
            }));
            await frappe.call({
                method: "frappe.client.save",
                args: { doc: bom_doc }
            });
            frappe.msgprint({
                title: "BOM Updated",
                message: `BOM <a href="/app/bom/${bom_doc.name}" target="_blank">${bom_doc.name}</a> has been updated.`,
                indicator: 'green'
            });
        } catch (err) {
            console.error("BOM update error:", err);
            frappe.msgprint("Error while updating BOM.");
        }
    }
});

// ----------- SALES ORDER CREATION -----------

function handle_sales_order_creation(frm) {
    const all_items = frm.doc.customer_worksheet_items || [];
    const bom_items = frm.doc.customer_bom_items || [];
    const items = all_items.filter(i => !i.sales_order_no);

    if (!items.length) {
        frappe.msgprint('All items already have Sales Orders.');
        return;
    }

    const grouped = group_items_for_sales_order(items);
    const html = render_items_table(grouped);

    const dialog = new frappe.ui.Dialog({
        title: 'Select Items to Create Sales Orders',
        size: 'large',
        fields: [{ fieldtype: 'HTML', fieldname: 'items_html' }],
        primary_action_label: 'Create',
        primary_action: () => process_sales_order_dialog(frm, dialog, grouped, bom_items)
    });

    dialog.fields_dict.items_html.$wrapper.html(html);
    dialog.show();
}

// Group items by item_code and order_type (for table and single selection per group)
function group_items_for_sales_order(items) {
    // key: item_code||order_type
    const grouped = {};
    items.forEach(item => {
        const key = item.item_code + '||' + (item.order_type || '');
        if (!grouped[key]) {
            grouped[key] = {
                ...item,
                count: 1,
                total_qty: parseFloat(item.qty) || 0
            };
        } else {
            grouped[key].count += 1;
            grouped[key].total_qty += parseFloat(item.qty) || 0;
        }
    });
    return Object.values(grouped);
}

function render_items_table(items) {
    return `
        <div style="max-height: 300px; overflow-y: auto;">
            <table class="table table-bordered">
                <thead>
                    <tr>
                        <th></th><th>Item Code</th><th>Item Name</th>
                        <th>Qty</th><th>Item Group</th><th>Order Type</th><th>Rows/Size</th>
                    </tr>
                </thead>
                <tbody>
                    ${items.map((item, i) => `
                        <tr>
                            <td><input type="checkbox" class="so-item-checkbox" data-key="${item.item_code}||${item.order_type || ''}" checked></td>
                            <td>${item.item_code}</td>
                            <td>${item.item_name}</td>
                            <td>${item.total_qty}</td>
                            <td>${item.item_group || ''}</td>
                            <td>${item.order_type || ''}</td>
                            <td>${item.count}</td>
                        </tr>
                    `).join('')}
                </tbody>
            </table>
        </div>`;
}

function process_sales_order_dialog(frm, dialog, grouped_items, bom_items) {
    // Find selected
    const selected_keys = [];
    dialog.fields_dict.items_html.$wrapper.find('.so-item-checkbox:checked').each(function () {
        selected_keys.push($(this).data('key'));
    });

    if (!selected_keys.length) {
        frappe.msgprint('Please select at least one item.');
        return;
    }

    // For each selected, filter items out of doc.customer_worksheet_items
    const to_create = (frm.doc.customer_worksheet_items || []).filter(item =>
        selected_keys.includes(item.item_code + '||' + (item.order_type || '')) && !item.sales_order_no
    );

    for (const item of to_create) {
        if (!item.order_type) {
            frappe.msgprint(`Order Type is missing for item: ${item.item_code}`);
            return;
        }
    }

    dialog.hide();
    proceed_sales_order_creation(frm, to_create, bom_items);
}

// Creates one SO per group/order-type/size, as in your original
async function proceed_sales_order_creation(frm, create_items, bom_items) {
    if (!create_items.length) return;

    // Group for sized/unsized
    const sized = create_items.filter(i => i.size);
    const unsized = create_items.filter(i => !i.size);

    // by order_type for sized
    const grouped_by_order_type = {};
    sized.forEach(item => {
        const k = item.order_type || "NoType";
        (grouped_by_order_type[k] = grouped_by_order_type[k] || []).push(item);
    });

    const sales_order_names = [];

    // Process for each group sequentially to avoid async surprises
    const processGroups = async (groups, bom_items) => {
        for (const items of groups) {
            await create_sales_order(frm, items, bom_items, sales_order_names);
        }
    };

    // Promise chains to ensure sequential execution
    await processGroups(Object.values(grouped_by_order_type), bom_items);
    for (const item of unsized) {
        await create_sales_order(frm, [item], bom_items, sales_order_names);
    }

    show_sales_orders(sales_order_names);
}

// Actually creates one SO for given items
async function create_sales_order(frm, items_list, bom_items, sales_order_names) {
    const company_abbr = await frappe.db.get_value("Company", frm.doc.company, "abbr")
        .then(res => res.message.abbr);
    const warehouse = `Stores - ${company_abbr}`;

    // Prepare items per item_code+size as before
    const groupedItems = {};
    for (const item of items_list) {
        const key = item.item_code + '||' + (item.size || '');
        (groupedItems[key] = groupedItems[key] || []).push(item);
    }
    for (const group of Object.values(groupedItems)) {
        const item = group[0]; // Use first as representative

        const so_doc = {
            doctype: "Sales Order",
            customer: frm.doc.customer,
            custom_department: frm.doc.department,
            // Both "factory_vendor" + custom_factory_vendor? (keep both as in original)
            factory_vendor: frm.doc.custom_factory_vendor,
            company: frm.doc.company,
            transaction_date: frm.doc.order_date,
            custom_sales_order_type: item.order_type,
            custom_factory_vendor: frm.doc.factory_vendor,
            custom_stone_vendor: frm.doc.stone_vendor,
            custom_other_vendor: frm.doc.other_vendor,
            items: [],
            custom_bom_items: []
        };

        // Find BOM
        const matching_bom = bom_items.find(b =>
            b.item_code === item.item_code && (!item.size || b.custom_size === item.size)
        );

        so_doc.items.push({
            item_code: item.item_code,
            item_name: item.item_name,
            uom: item.uom,
            custom_size: item.size,
            bom_no: item.default_bom,
            custom_customer_worksheet_no: frm.doc.name,
            rate: item.rate,
            delivery_date: item.eta,
            image_view: item.image_view,
            custom_product_image: item.image_view,
            custom_supporting_documents: frm.doc.supporting_documents,
            qty: matching_bom ? matching_bom.qty : item.qty,
            warehouse: warehouse,
            bom: matching_bom ? matching_bom.bom_no : item.default_bom,
            custom_item_bom: item.default_bom || (matching_bom ? matching_bom.bom_no : null),
            custom_our_responsibility: (matching_bom ? matching_bom.our_responsibility : null)
        });

        if (item.default_bom) {
            so_doc.custom_item_bom = item.default_bom;
            // Pull BOM items for custom_bom_items ONLY for first SO item (old code logic)
            const bomDoc = await frappe.db.get_doc('BOM', item.default_bom);
            (bomDoc.items || []).forEach(bomItem => {
                so_doc.custom_bom_items.push({
                    item_code: bomItem.item_code,
                    item_name: bomItem.item_name,
                    qty: bomItem.qty || 1,
                    uom: bomItem.uom,
                    rate: bomItem.rate || 0,
                    amount: bomItem.amount || 0,
                    description: bomItem.description,
                    custom_item_group: bomItem.custom_item_group || '',
                    custom_selling_amount: bomItem.custom_selling_amount || '',
                    custom_gemstone: bomItem.custom_gemstone,
                    custom_stone_treatment_list: bomItem.custom_stone_treatment_list,
                    custom_merch_color__attribute: bomItem.custom_merch_color__attribute,
                    custom_country_of_origin: bomItem.custom_country_of_origin,
                    custom_grade: bomItem.custom_grade,
                    custom_stone_pieces: bomItem.custom_stone_pieces,
                    custom_avg_carat_weight: bomItem.custom_avg_carat_weight,
                    custom_sku_carat_weight: bomItem.custom_sku_carat_weight,
                    custom_cut: bomItem.custom_cut,
                    custom_setting_type: bomItem.custom_setting_type,
                    custom_metal_weight: bomItem.custom_metal_weight,
                    custom_sku_metal_weight: bomItem.custom_sku_metal_weight,
                    custom_metal_group: bomItem.custom_metal_group,
                    custom_selling_rate: bomItem.custom_selling_rate,
                    custom_sku_weight: bomItem.custom_sku_weight,
                    custom_ext_qty_required: bomItem.custom_ext_qty_required,
                    custom_oh: bomItem.custom_oh,
                    custom_net_balance_required: bomItem.custom_net_balance_required,
                    custom_our_responsibility: bomItem.custom_our_responsibility,
                    custom_with_jback: bomItem.custom_with_jback,
                });
            });
        }

        const res = await frappe.call({
            method: "frappe.client.insert",
            args: { doc: so_doc }
        });
        const so_name = res.message && res.message.name;
        if (so_name) {
            sales_order_names.push(so_name);

            // Attach file if in worksheet
            if (frm.doc.supporting_documents) {
                await frappe.call({
                    method: "frappe.client.insert",
                    args: {
                        doc: {
                            doctype: "File",
                            file_url: frm.doc.supporting_documents,
                            attached_to_doctype: "Sales Order",
                            attached_to_name: so_name
                        }
                    }
                });
            }

            // Set SO# and status on source worksheet items (all matching, old code did by qty and size)
            group.forEach(child => {
                (frm.doc.customer_worksheet_items || []).forEach(row => {
                    if (row.item_code === child.item_code &&
                        (row.size === child.size || !child.size) &&
                        row.qty === child.qty) {
                        row.sales_order_no = so_name;
                        row.sales_order_status = res.message.status || "Draft";
                    }
                });
            });
            frm.refresh_field('customer_worksheet_items');
            toggle_create_so_button(frm);
            frm.save();
        }
    }
}

