                    frappe.set_route("Form", "Sales Order", sales_orders[0]);
                } else {
                    frappe.prompt(
                        [
                            {
                                label: "Select Sales Order",
                                fieldname: "sales_order",
                                fieldtype: "Select",
                                options: sales_orders,
                                reqd: 1
                            }
                        ],
                        (values) => {
