if (!window.__customer_worksheet_handler_initialized__) {
    window.__customer_worksheet_handler_initialized__ = true;

    const BOMCreator = {
        current_dialog: null,
        creating_bom: false,

        init() {
            this.setupEventHandlers();
        },

        setupEventHandlers() {
            // Main form events
            frappe.ui.form.on('Customer Worksheet', {
                setup: this.handleSetup.bind(this),
                clear: this.handleClear.bind(this),
                search_button: this.handleSearch.bind(this),
                create_bom: this.createBOM.bind(this),
                finished_goods_item: this.handleFinishedGoodsItem.bind(this),
                refresh: this.handleRefresh.bind(this),
                existing_bom: this.handleExistingBOM.bind(this),
                update_bom: this.updateBOM.bind(this),
                onload: this.handleOnLoad.bind(this),
                search_bom: this.searchBOM.bind(this),
                add_default_items: this._addDefaultBOMItems.bind(this),
                bom_id: this.updateBOMTotals.bind(this),

                onload: function(frm) {
                    frm.script = calculateLogic;
                    frm.script.recalculateAllRows(frm);
                    frm.script.updateBOM = updateBOM;
                    toggleBOMButtons(frm);
                },

                refresh: function(frm) {
                    frm.script = calculateLogic;
                    frm.script.recalculateAllRows(frm);
                    frm.script.updateBOM = updateBOM;
                    toggleBOMButtons(frm);
                }
            });

            // Child table events
            this.setupChildTableEvents();
        },

        setupChildTableEvents() {
            const bomItemsEvents = {
                qty: this.updateBOMTotals.bind(this),
                rate: this.updateBOMTotals.bind(this),
                custom_selling_rate: this.updateBOMTotals.bind(this),
                custom_selling_amount: this.updateBOMTotals.bind(this),
                amount: this.updateBOMTotals.bind(this),
                selling_amount: this.updateBOMTotals.bind(this)
            };

            const bomCreatorEvents = {
                custom_ext_qty_required: this.calculateNetBalance.bind(this),
                custom_oh: this.calculateNetBalance.bind(this),
                form_render: this.handleFormRender.bind(this),
                item_code: this.handleItemCodeChange.bind(this),
                custom_gemstone: this.handleGemstoneChange.bind(this),
                custom_grade: this.updateBOMItemDescription.bind(this),
                custom_cut: this.updateBOMItemDescription.bind(this),
                custom_setting_type: this.updateBOMItemDescription.bind(this),
                custom_merch_color: this.updateBOMItemDescription.bind(this),
                custom_country_of_origin: this.updateBOMItemDescription.bind(this),
                custom_length: this.updateBOMItemDescription.bind(this),
                custom_weight_perpiece: this.updateBOMItemDescription.bind(this),
                custom_our_responsibility: this.updateBOMItemDescription.bind(this),
                custom_merch_color__attribute: this.updateBOMItemDescription.bind(this),

                // Dynamic calculation events
                custom_stone_pieces: (frm, cdt, cdn) => frm.script.calculateQtyAndAll(frm, cdt, cdn),
                custom_metal_weight: (frm, cdt, cdn) => frm.script.calculateQtyAndAll(frm, cdt, cdn),
                custom_avg_carat_weight: (frm, cdt, cdn) => frm.script.calculateQtyAndAll(frm, cdt, cdn),
                uom: (frm, cdt, cdn) => frm.script.calculateQtyAndAll(frm, cdt, cdn),
                custom_item_group: (frm, cdt, cdn) => frm.script.calculateQtyAndAll(frm, cdt, cdn),
                qty: (frm, cdt, cdn) => frm.script.calculateAll(frm, cdt, cdn),
                rate: (frm, cdt, cdn) => frm.script.calculateAll(frm, cdt, cdn),
                custom_selling_rate: (frm, cdt, cdn) => frm.script.calculateAll(frm, cdt, cdn)
            };

            frappe.ui.form.on('Customer Worksheet BOM Items', bomItemsEvents);
            frappe.ui.form.on('Customer Worksheet BOM Creator Items', bomCreatorEvents);
        },

        // ==================== FORM HANDLERS ====================
        handleSetup(frm, cdt, cdn) {
            const row = locals[cdt][cdn];
            if (row?.custom_gemstone) {
                this.fetchCountryOfOrigin(frm, row.custom_gemstone);
            }
        },

        handleClear(frm) {
            const fieldsToReset = ['keyword_search', 'item_group_', 'existing_bom', 'finished_goods_item'];
            fieldsToReset.forEach(field => frm.set_value(field, ''));
            
            if (frm.doc.bom_items?.length) {
                frm.doc.bom_items = [];
                frm.refresh_field('bom_items');
            }
        },

        async handleSearch(frm) {
            try {
                const { items, matching_items } = await this.searchItems(frm);
                
                if (matching_items.length > 0) {
                    frm.set_value('item_code_', matching_items[0].item_code);
                    frm.set_value('item_name_', matching_items[0].item_name);
                }
                
                this.showItemSelectionDialog(frm, matching_items);
            } catch (err) {
                console.error("Search error:", err);
                frappe.msgprint("Error while searching items.");
            }
        },

        async searchItems(frm) {
            const item_group = frm.doc.item_group_;
            const keywords = frm.doc.keyword_search;
            
            let filters = { disabled: 0 };
            if (item_group) filters.item_group = item_group;

            const items = await frappe.db.get_list('Item', {
                fields: ['item_code', 'item_name', 'description', 'item_group', 'stock_uom', 
                        'custom_gemstone', 'custom_metal_group', 'custom_material_id'],
                filters,
                limit: 500000
            });

            let matching_items = items;
            if (keywords) {
                const keyword_list = keywords.toLowerCase().split(/\s+/).filter(Boolean);
                matching_items = items.filter(item => {
                    const content = `${item.item_code} ${item.item_name || ''} ${item.description || ''}`.toLowerCase();
                    return keyword_list.every(kw => content.includes(kw));
                });
            }

            return { items, matching_items };
        },

        handleFinishedGoodsItem(frm) {
            this.toggleBOMButtons(frm);
            if (frm.doc.finished_goods_item) {
                this.insertDefaultBOMItems(frm);
            }
        },

        handleRefresh(frm) {
            this.toggleBOMButtons(frm);
        },

        async handleExistingBOM(frm) {
            this.toggleBOMButtons(frm);
            if (!frm.doc.existing_bom) return;

            try {
                frappe.dom.freeze("Loading BOM items...");
                const bom = await frappe.call({
                    method: "frappe.client.get",
                    args: { doctype: "BOM", name: frm.doc.existing_bom }
                });

                this.populateBOMItems(frm, bom.message);
                frappe.dom.unfreeze();
            } catch (err) {
                console.error("Error loading BOM items:", err);
                frappe.dom.unfreeze();
                frappe.msgprint("Error while loading BOM items.");
            }
        },

        populateBOMItems(frm, bom_doc) {
            frm.clear_table('bom_items');
            
            const fieldMappings = {
                item_code: 'item_code', item_name: 'item_name', custom_item_group: 'custom_item_group',
                qty: 'qty', uom: 'uom', rate: 'rate', amount: 'amount', description: 'description',
                custom_selling_rate: 'custom_selling_rate', custom_selling_amount: 'custom_selling_amount',
                custom_gemstone: 'custom_gemstone', custom_stone_treatment_list: 'custom_stone_treatment_list',
                custom_merch_color__attribute: 'custom_merch_color__attribute',
                custom_country_of_origin: 'custom_country_of_origin', custom_grade: 'custom_grade',
                custom_stone_pieces: 'custom_stone_pieces', custom_avg_carat_weight: 'custom_avg_carat_weight',
                custom_sku_carat_weight: 'custom_sku_carat_weight', custom_cut: 'custom_cut',
                custom_setting_type: 'custom_setting_type', custom_metal_weight: 'custom_metal_weight',
                custom_sku_metal_weight: 'custom_sku_metal_weight', custom_metal_group: 'custom_metal_group',
                custom_sku_weight: 'custom_sku_weight', custom_ext_qty_required: 'custom_ext_qty_required',
                custom_oh: 'custom_oh', custom_net_balance_required: 'custom_net_balance_required',
                custom_our_responsibility: 'custom_our_responsibility', custom_with_jback: 'custom_with_jback'
            };

            (bom_doc.items || []).forEach(item => {
                const child = frm.add_child('bom_items');
                
                Object.entries(fieldMappings).forEach(([childField, itemField]) => {
                    child[childField] = item[itemField] || (childField === 'rate' ? 0.0 : '');
                });
                
                child.bom_no = frm.doc.existing_bom;
            });

            frm.refresh_field('bom_items');
        },

        handleOnLoad(frm) {
            frm.set_query('existing_bom', () => {
                if (!frm.doc.finished_goods_item) {
                    frappe.msgprint("Please select a Finished Goods Item first.");
                    return {};
                }
                return { filters: { item: frm.doc.finished_goods_item } };
            });
        },

        // ==================== BOM OPERATIONS ====================
        async createBOM(frm) {
            if (this.creating_bom) return;
            this.creating_bom = true;

            try {
                const validation = this.validateBOMCreation(frm);
                if (!validation.valid) {
                    frappe.msgprint(validation.message);
                    return;
                }

                await this.unsetExistingDefaultBOMs(frm.doc.finished_goods_item);
                const items = this.prepareBOMItems(frm.doc.bom_items);
                const bom_doc = await this.createBOMDocument(frm.doc.finished_goods_item, items);
                const bom_name = bom_doc.message.name;

                await this.setDefaultBOM(bom_name);
                this.updateWorksheetWithBOM(frm, bom_name);
                
                await frm.save();
                await frm.reload_doc();

                this.showBOMCreatedMessage(bom_name);
                this.promptToInsertFinishedGoods(frm);

            } catch (error) {
                console.error("BOM creation error:", error);
            } finally {
                this.creating_bom = false;
            }
        },

        validateBOMCreation(frm) {
            if (!frm.doc.bom_items?.length) {
                return { valid: false, message: "No items found in BOM Items table." };
            }
            if (!frm.doc.finished_goods_item) {
                return { valid: false, message: "Please select a Finished Goods Item." };
            }
            return { valid: true };
        },

        async unsetExistingDefaultBOMs(fg_item) {
            const existing_defaults = await frappe.db.get_list('BOM', {
                filters: { item: fg_item, is_default: 1, docstatus: 0 },
                fields: ['name']
            });

            for (const bom of existing_defaults) {
                await frappe.call({
                    method: 'frappe.client.set_value',
                    args: { doctype: 'BOM', name: bom.name, fieldname: 'is_default', value: 0 }
                });
            }
        },

        prepareBOMItems(bom_items) {
            const fieldMappings = {
                item_code: 'item_code', item_name: 'item_name', qty: 'qty', uom: 'uom',
                rate: 'rate', amount: 'amount', description: 'description',
                item_group: 'custom_item_group', custom_selling_rate: 'custom_selling_rate',
                custom_selling_amount: 'custom_selling_amount', custom_gemstone: 'custom_gemstone',
                custom_stone_treatment_list: 'custom_stone_treatment_list',
                custom_merch_color__attribute: 'custom_merch_color__attribute',
                custom_country_of_origin: 'custom_country_of_origin', custom_grade: 'custom_grade',
                custom_stone_pieces: 'custom_stone_pieces', custom_avg_carat_weight: 'custom_avg_carat_weight',
                custom_sku_carat_weight: 'custom_sku_carat_weight', custom_cut: 'custom_cut',
                custom_setting_type: 'custom_setting_type', custom_metal_weight: 'custom_metal_weight',
                custom_sku_metal_weight: 'custom_sku_metal_weight', custom_metal_group: 'custom_metal_group',
                custom_sku_weight: 'custom_sku_weight', custom_ext_qty_required: 'custom_ext_qty_required',
                custom_oh: 'custom_oh', custom_net_balance_required: 'custom_net_balance_required',
                custom_our_responsibility: 'custom_our_responsibility', custom_with_jback: 'custom_with_jback'
            };

            return bom_items.map(row => {
                const item = {};
                Object.entries(fieldMappings).forEach(([bomField, rowField]) => {
                    item[bomField] = row[rowField] || (bomField === 'qty' ? 1 : bomField === 'uom' ? 'Piece' : '');
                });
                return item;
            });
        },

        async createBOMDocument(fg_item, items) {
            return await frappe.call({
                method: "frappe.client.insert",
                freeze: true,
                freeze_message: "Creating BOM...",
                args: {
                    doc: {
                        doctype: "BOM", item: fg_item, quantity: 1,
                        is_active: 1, docstatus: 0, items: items
                    }
                }
            });
        },

        async setDefaultBOM(bom_name) {
            await frappe.call({
                method: 'frappe.client.set_value',
                args: { doctype: 'BOM', name: bom_name, fieldname: 'is_default', value: 1 }
            });
        },

        updateWorksheetWithBOM(frm, bom_name) {
            (frm.doc.bom_items || []).forEach(row => row.bom_no = bom_name);
            frm.refresh_field('bom_items');

            (frm.doc.customer_worksheet_items || []).forEach(row => {
                row.default_bom = row.item_code === frm.doc.finished_goods_item ? bom_name : '';
            });
            frm.refresh_field('customer_worksheet_items');
        },

        showBOMCreatedMessage(bom_name) {
            frm.fields_dict.bom_status?.$wrapper?.html(
                `<div style="color:green;"><strong>BOM Created:</strong> <a href="/app/bom/${bom_name}" target="_blank">${bom_name}</a></div>`
            );

            frappe.msgprint({
                title: "BOM Created",
                message: `New BOM created: <a href="/app/bom/${bom_name}" target="_blank">${bom_name}</a>`,
                indicator: 'green'
            });
        },

        promptToInsertFinishedGoods(frm) {
            const fg_item = frm.doc.finished_goods_item;
            const exists = frm.doc.customer_worksheet_items.some(i => i.item_code === fg_item);
            
            if (exists) return;

            setTimeout(() => {
                frappe.confirm(
                    `Do you wish to insert "<b>${fg_item}</b>" into the worksheet?`,
                    async () => {
                        try {
                            const item = await frappe.db.get_doc('Item', fg_item);
                            const child = frm.add_child('customer_worksheet_items');
                            Object.assign(child, {
                                item_code: fg_item, item_name: item.item_name,
                                item_group: item.item_group, uom: item.stock_uom,
                                qty: 1, rate: item.valuation_rate || 0
                            });
                            frm.refresh_field('customer_worksheet_items');
                        } catch (err) {
                            console.error("Failed to fetch item:", err);
                            frappe.msgprint("Failed to fetch item details.");
                        }
                    }
                );
            }, 500);
        },

        async updateBOM(frm) {
            if (!frm.doc.existing_bom) {
                frappe.msgprint("No existing BOM selected.");
                return;
            }

            try {
                const bom_doc = await frappe.call({
                    method: "frappe.client.get",
                    args: { doctype: "BOM", name: frm.doc.existing_bom }
                });

                if (bom_doc.message.docstatus === 1) {
                    this.handleSubmittedBOM();
                    return;
                }

                bom_doc.message.items = this.prepareBOMItemsForUpdate(frm.doc.bom_items);

                await frappe.call({
                    method: "frappe.client.save",
                    args: { doc: bom_doc.message }
                });

                frappe.msgprint({
                    title: "BOM Updated",
                    message: `BOM <a href="/app/bom/${bom_doc.message.name}" target="_blank">${bom_doc.message.name}</a> has been updated.`,
                    indicator: 'green'
                });
            } catch (error) {
                console.error("BOM update error:", error);
            }
        },

        handleSubmittedBOM() {
            frappe.msgprint({
                title: "BOM is Submitted",
                message: "This BOM is submitted. Please create a new BOM.",
                indicator: "red"
            });

            setTimeout(() => {
                const updateBtn = document.querySelector('button:contains("Update BOM")');
                const createBtn = document.querySelector('button:contains("Create BOM")');
                if (updateBtn) updateBtn.style.display = 'none';
                if (createBtn) createBtn.style.display = 'inline-block';
            }, 300);
        },

