        // ==================== CALCULATION FUNCTIONS ====================
        calculateNetBalance(frm, cdt, cdn) {
            const row = locals[cdt][cdn];
            if (!row) return;

            const extQty = flt(row.custom_ext_qty_required) || 0;
            const onHand = flt(row.custom_oh) || 0;
            const netBalance = extQty - onHand;

            frappe.model.set_value(cdt, cdn, 'custom_net_balance_required', netBalance);
        },

        // ==================== ITEM DESCRIPTION FUNCTIONS ====================
        handleItemCodeChange(frm, cdt, cdn) {
            setTimeout(() => this.updateBOMItemDescription(frm, cdt, cdn), 300);
        },

        handleGemstoneChange(frm, cdt, cdn) {
            this.updateBOMItemDescription(frm, cdt, cdn);
            this.updateCountryOfOriginOptions(frm, cdt, cdn);
        },

        updateBOMItemDescription(frm, cdt, cdn) {
            const row = locals[cdt][cdn];
            if (!row) return;

            const existing_desc = row.description || '';
            const descriptionFields = {
                'Item Name': 'item_name', 'Item Group': 'custom_item_group', 'Gemstone': 'custom_gemstone',
                'Grade': 'custom_grade', 'Cut': 'custom_cut', 'Setting Type': 'custom_setting_type',
                'Merch Color': 'custom_merch_color', 'Pieces': 'custom_stone_pieces',
                'Country': 'custom_country_of_origin', 'SKU Weight': 'custom_sku_weight',
                'Avg Carat': 'custom_avg_carat_weight', 'Metal Weight': 'custom_metal_weight',
                'Length': 'custom_length', 'Weight/Piece': 'custom_weight_perpiece',
                'Responsibility': 'custom_our_responsibility', 'Merch Color': 'custom_merch_color__attribute'
            };

            const parts = [];
            Object.entries(descriptionFields).forEach(([label, field]) => {
                const value = row[field];
                const searchText = `${label}: ${value}`;
                if (value && !existing_desc.includes(searchText)) {
                    parts.push(searchText);
                }
            });

            if (parts.length > 0) {
                const updated_desc = existing_desc + (existing_desc ? ' | ' : '') + parts.join(' | ');
                frappe.model.set_value(cdt, cdn, 'description', updated_desc);
                frm.fields_dict["bom_items"].grid.refresh_row(cdn);
            }
        },

        // ==================== COUNTRY OF ORIGIN FUNCTIONS ====================
        handleFormRender(frm, cdt, cdn) {
            const row = locals[cdt][cdn];
            this.updateCountryOfOriginOptions(frm, cdt, cdn);

            if (row.custom_coutry) {
                frappe.model.set_value(cdt, cdn, "custom_country_of_origin", row.custom_coutry);
            }
        },

        updateCountryOfOriginOptions(frm, cdt, cdn) {
            const row = locals[cdt][cdn];
            const grid_field = frm.fields_dict["bom_items"].grid;

            if (!row.custom_gemstone) {
                frappe.meta.get_docfield("Customer Worksheet BOM Creator Items", "custom_country_of_origin").get_query = () => ({});
                frappe.model.set_value(cdt, cdn, "custom_country_of_origin", null);
                grid_field.refresh();
                return;
            }

            frappe.call({
                method: "get_country_of_origin",
                args: { gemstone: row.custom_gemstone },
                callback: function(r) {
                    if (r.exc) {
                        console.error("Error fetching countries:", r.exc);
                        return;
                    }

                    if (r.data) {
                        const unique_countries = [...new Set(r.data.map(entry => entry[1]))];
                        grid_field.update_docfield_property("custom_country_of_origin", "options", unique_countries);
                    }
                }
            });
        }
    };

