function bindPopupToTreatmentField(frm) {
    const $table = frm.fields_dict.items.grid.wrapper;

    $table.off('click', "[data-fieldname='custom_stone_treatment_list']");

    $table.on('click', "[data-fieldname='custom_stone_treatment_list']", function (e) {
        e.stopPropagation();

        const grid_row = $(this).closest('.grid-row');
        const row_name = grid_row.attr('data-name');
        const grid = frm.fields_dict.items.grid;
        const row = grid.grid_rows_by_docname[row_name].doc;

        if ($(this).data('popup-opened')) return;
        $(this).data('popup-opened', true);

        const all_rows = frm.doc.items || [];
        let start_index = all_rows.findIndex(r => r.name === row.name);

        function openTreatmentDialog(index) {
            if (index >= all_rows.length) return;

            const current_row = all_rows[index];
            if (current_row.custom_item_group !== "Stone") return;

            let currentDialogSelected = new Set();
            let searchTimeout;

            const dialog = new frappe.ui.form.MultiSelectDialog({
                doctype: 'Stone Treatment',
                target: frm,
                setters: {},
                add_filters_group: 0,
                allow_multiple: true,
                action: function () {
                    const treatment_list = Array.from(currentDialogSelected).join(', ');
                    frappe.model.set_value(current_row.doctype, current_row.name, 'custom_stone_treatment_list', treatment_list);
                    this.dialog.hide();
                    setTimeout(() => openTreatmentDialog(index + 1), 400);
                },
                primary_action_label: 'Insert',
                get_query: () => ({ filters: {} }),
                action_on_cancel: function () {}
            });

            const waitForDialog = setInterval(() => {
                if (dialog.dialog && dialog.dialog.$wrapper && dialog.dialog.$wrapper.is(':visible')) {
                    clearInterval(waitForDialog);

                    dialog.dialog.$body.find('.custom-header').remove();

                    const display_index = index + 1;
                    const item_code = current_row.item_code || '-';
                    const item_name = current_row.item_name || '-';
                    const stone_pieces = current_row.custom_stone_pieces || '0';

                    const header_html = `
                        <div class="custom-header" style="padding: 10px; background-color: #f1f5f9; border-bottom: 1px solid #ccc; margin-bottom: 10px;">
                            <strong>Row-${display_index}:</strong> ${item_code}: ${item_name} – ${stone_pieces} Stone Pieces
                            <div id="selected-treatments-${index}" style="margin-top: 5px;">
                                <span style="color: black; font-weight: 500;">Selected:</span> 
                                <span style="color: green; font-weight: 500;">None</span>
                            </div>
                        </div>
                    `;
                    dialog.dialog.$body.prepend($(header_html));

                    const getCheckboxLabel = ($checkbox) => {
                        return $checkbox.attr('data-item-name') ||
                               $checkbox.closest('.list-row-check').attr('data-item-name') ||
                               $checkbox.parents('[data-item-name]').first().attr('data-item-name') ||
                               $checkbox.next().text().trim();
                    };

                    const restoreSelections = () => {
                        dialog.dialog.$body.find('input[type="checkbox"]').each(function() {
                            const label = getCheckboxLabel($(this));
                            if (label && currentDialogSelected.has(label)) {
                                $(this).prop('checked', true);
                            }
                        });
                    };

                    const updateLiveSelection = () => {
                        dialog.dialog.$body.find('input[type="checkbox"]:checked').each(function() {
                            const label = getCheckboxLabel($(this));
                            if (label && label !== 'Name' && label !== '') {
                                currentDialogSelected.add(label);
                            }
                        });

                        dialog.dialog.$body.find('input[type="checkbox"]:not(:checked)').each(function() {
                            const label = getCheckboxLabel($(this));
                            if (label && label !== 'Name' && label !== '') {
                                currentDialogSelected.delete(label);
                            }
                        });

                        const selectedText = currentDialogSelected.size > 0 ? Array.from(currentDialogSelected).join(', ') : 'None';
                        $(`#selected-treatments-${index}`).html(`
                            <span style="color: black; font-weight: 500;">Selected:</span> 
                            <span style="color: green; font-weight: 500;">${selectedText}</span>
                        `);
                    };

                    // Live update on checkbox click
                    dialog.dialog.$body.off('click.liveselect change.liveselect');
                    dialog.dialog.$body.on('click.liveselect change.liveselect', 'input[type="checkbox"], .list-row-check', function() {
                        setTimeout(updateLiveSelection, 50);
                    });

                    const observer = new MutationObserver(function(mutations) {
                        let shouldUpdate = mutations.some(mutation =>
                            mutation.type === 'childList' && (mutation.addedNodes.length > 0 || mutation.removedNodes.length > 0)
                        );
                        if (shouldUpdate) {
                            clearTimeout(searchTimeout);
                            searchTimeout = setTimeout(() => {
                                restoreSelections();
                                updateLiveSelection();
                            }, 200);
                        }
                    });

                    observer.observe(dialog.dialog.$body[0], { childList: true, subtree: true });

                    setTimeout(() => {
                        const searchInput = dialog.dialog.$body.find('input[type="text"], input[data-fieldtype="Data"]').first();
                        if (searchInput.length) {
                            searchInput.on('input keyup', function() {
                                clearTimeout(searchTimeout);
                                searchTimeout = setTimeout(() => {
                                    restoreSelections();
                                    updateLiveSelection();
                                }, 500);
                            });
                        }
                    }, 1000);

                    setTimeout(updateLiveSelection, 500);
                    setTimeout(updateLiveSelection, 1000);

                    dialog.dialog.onhide = function() {
                        observer.disconnect();
                        $table.find("[data-fieldname='custom_stone_treatment_list']").data('popup-opened', false);
                    };
                }
            }, 50);
        }

        openTreatmentDialog(start_index);
    });
}

