submit_document: async function(frm) {
    for (let item of frm.doc.items_details) {
        item.status = "Submitted";

        if (item.sales_order) {
            await frappe.db.get_value("Sales Order", item.sales_order, "status")
                .then(res => {
                    if (res && res.message) {
                        item.sales_order_status = res.message.status;
                    }
                });
        }
        if (item.purchase_order) {
            await frappe.db.get_value("Purchase Order", item.purchase_order, "status")
                .then(res => {
                    if (res && res.message) {
                        item.purchase_order_status = res.message.status;
                    }
                });
        }
    }

    frm.refresh_field("items_details");
    frm.set_value("status", "Submitted");
    frm.refresh_field("status");

    let document_to_submit = [];

    if (frm.doc.items_details.length > 0) {
        frm.doc.items_details.forEach(item => {
            if (item.bom) {
                document_to_submit.push({ "doctype": "BOM", "name": item.bom });
            }
        });

        frm.doc.items_details.forEach(item => {
            if (item.sales_order) {
                document_to_submit.push({ "doctype": "Sales Order", "name": item.sales_order });
            }
        });

        frappe.call({
            method: "submit_documents",
            args: {
                doc_list: JSON.stringify(document_to_submit)
            },
            callback: function(r) {
                if (r.message) {
                    console.log("Submission result:", r.message);
                    frappe.msgprint("Documents processed: " + r.message.length);
                }
            }
        });
    }
}

