            frm.refresh_field("items");
            frm.set_value('item_count', total_items.length);
            calculate_total_net_weight(frm);
            return;
        }

        frappe.call({
            method: "frappe.client.get",
            args: {
                doctype: doc_type,
                name: selected_docs[index]
            },
            callback: function(r) {
                if (r.message) {
                    let items = r.message.items || [];

                    items.forEach(function(item) {
                        let child = frm.add_child("items");
                        child.item_code = item.item_code;
                        child.item_name = item.item_name;
                        child.qty = item.qty;
                        child.uom = item.uom; 
                        child.weight_uom ="Kilogram";
