                        frm.set_value('requested_company_address', r.message.company_address);
                    }
                    if (r.message.company_address_display) {
                        frm.set_value('requested_company_address_display', r.message.company_address_display);
                    }
                }
            })
            .catch(err => {
                console.error('Error fetching company address:', err);
            });
    } else if (frm.doc.direct_supply === "Yes") {
        frm.set_value('requested_company_address', '');
        frm.set_value('requested_company_address_display', '');
        
        frappe.db.get_value('Sales Order', frm.doc.sku_sales_order, 'custom_factory_vendor')
