function calculate_pending(frm) {
    let pending_piece = 0;
    if (frm.doc.required_piece && frm.doc.fulfilled_piece) {
        pending_piece = frm.doc.required_piece - frm.doc.fulfilled_piece;
    } else if (frm.doc.required_piece) {
        pending_piece = frm.doc.required_piece;
    }
    frm.set_value("pending_piece", pending_piece);

    frm.toggle_display("pending_piece", pending_piece >= 0);

    let pending_carat = 0;
    if (frm.doc.required_carat && frm.doc.fulfilled_carat) {
        pending_carat = frm.doc.required_carat - frm.doc.fulfilled_carat;
    } else if (frm.doc.required_carat) {
        pending_carat = frm.doc.required_carat;
    }
    frm.set_value("pending_carat", pending_carat);

    frm.toggle_display("pending_carat", pending_carat >= 0);
}



