    let total_piece = 0;
    let total_carat = 0;

    (frm.doc.stone_request_fulfillment || []).forEach(row => {
        total_piece += row.confirmed_piece || 0;
        total_carat += row.confirmed_carat || 0;
    });

    frm.set_value("fulfilled_piece", total_piece);
    frm.set_value("fulfilled_carat", total_carat);
}

