// Core calculation functions
function calculate_requested_carats(frm) {
    if (frm.doc.avg_carat_weight && frm.doc.required_pieces) {
        frm.set_value("requested_carats", frm.doc.avg_carat_weight * frm.doc.required_pieces);
    }
}

function calculate_pending(frm) {
    // Calculate pending pieces
    let pending_pieces = 0;
    if (frm.doc.required_pieces && frm.doc.pieces_received) {
        pending_pieces = frm.doc.required_pieces - frm.doc.pieces_received;
    } else if (frm.doc.required_pieces) {
        pending_pieces = frm.doc.required_pieces;
    }
    frm.set_value("pending_pieces", pending_pieces);
    frm.toggle_display("pending_pieces", pending_pieces >= 0);

    // Calculate pending carat
    let pending_carat = 0;
    if (frm.doc.requested_carats && frm.doc.carat_received) {
        pending_carat = frm.doc.requested_carats - frm.doc.carat_received;
    } else if (frm.doc.requested_carats) {
        pending_carat = frm.doc.requested_carats;
    }
    frm.set_value("pending_carat", pending_carat);
    frm.toggle_display("pending_carat", pending_carat >= 0);
}

