// Initialize dialog with common properties
function initialize_dialog(d, config) {
    d._current_page = 1;
    d._items_per_page = 20;
    d._total_items = 0;
    d._total_pages = 0;
    d._is_searching = false;
    d._search_term = '';
    d._searchTimeout = null;
    d._selected_item = null;

    // Setup search functionality
    setup_search_handler(d, config);
    setup_clear_button(d, config);
}

// Setup search input handler
function setup_search_handler(d, config) {
    d.get_field(config.search_field).df.change = function() {
        if (d._searchTimeout) {
            clearTimeout(d._searchTimeout);
        }
        
        let search_term = this.get_value().trim();
        
        if (search_term && search_term.length >= 2) {
            // update_status(d, config, `Searching for "${search_term}"...`);
            d._searchTimeout = setTimeout(() => {
                search_items(d, config, search_term);
            }, 300);
        } else if (search_term.length === 0) {
            reset_to_all_items(d, config);
        } else {
            update_status(d, config, "Type at least 2 characters to search...");
        }
    };
}

// Setup clear button functionality
function setup_clear_button(d, config) {
    d.$wrapper.find(`#${config.clear_btn_id}`).on('click', function() {
        d.get_field(config.search_field).set_value('');
        reset_to_all_items(d, config);
        $(this).hide();
    });
}

// Generic data loading function
function load_initial_data(d, config) {
    update_status(d, config, "Loading items...");
    load_page(d, config, 1);
    
    frappe.call({
        method: "frappe.client.get_count",
        args: {
            doctype: config.doctype,
            filters: config.filters
        }
    }).then(r => {
        d._total_items = r.message || 0;
        d._total_pages = Math.ceil(d._total_items / d._items_per_page);
        update_status(d, config, `Total items ${d._total_items} and page 1 of ${d._total_pages}`);
        update_pagination(d, config);
    });
}

// Generic page loading
function load_page(d, config, page_number) {
    d._current_page = page_number;
    let start = (page_number - 1) * d._items_per_page;
    
    update_status(d, config, `Loading page ${page_number}...`);
    
    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: config.doctype,
            filters: config.filters,
            fields: config.db_fields,
            limit_start: start,
            limit_page_length: d._items_per_page,
            order_by: config.doctype === "Stone Request" ? "creation desc" : "item_code"
        }
    }).then(r => {
        let items = r.message || [];
        update_items_container(d, config, items);
        
        let end_item = Math.min(start + d._items_per_page, d._total_items);
        update_status(d, config, `Showing ${start + 1}-${start + items.length} of ${d._total_items} items (Page ${page_number} of ${d._total_pages})`);
        update_pagination(d, config);
    }).catch(error => {
        console.error("Error loading page:", error);
        update_items_container(d, config, [], "Error loading items.");
    });
}

// Generic search function
function search_items(d, config, search_term) {
    if (d._searchTimeout) {
        clearTimeout(d._searchTimeout);
    }
    
    d._is_searching = true;
    d._search_term = search_term;
    d._current_page = 1;
    
    // update_status(d, config, `Searching for "${search_term}"...`);
    
    let or_filters = [
        ["name", "like", `%${search_term}%`],
        ["item_code", "like", `%${search_term}%`],
        ["item_name", "like", `%${search_term}%`]
    ];
    
    if (config.doctype === "Stone Request") {
        or_filters.push(["material_id", "like", `%${search_term}%`]);
    } else {
        or_filters.push(["custom_material_id", "like", `%${search_term}%`]);
    }
    
    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: config.doctype,
            filters: config.filters,
            or_filters: or_filters,
            fields: config.db_fields,
            limit_start: 0,
            limit_page_length: d._items_per_page,
            order_by: config.doctype === "Stone Request" ? "creation desc" : "item_code"
        }
    }).then(r => {
        let items = r.message || [];
        update_items_container(d, config, items);
        
        // Get search count
        frappe.call({
            method: "frappe.client.get_count",
            args: {
                doctype: config.doctype,
                filters: config.filters,
                or_filters: or_filters
            }
        }).then(count_r => {
            let total_found = count_r.message || 0;
            d._search_total_items = total_found;
            d._search_total_pages = Math.ceil(total_found / d._items_per_page);
            
            // if (total_found === 0) {
            //     update_status(d, config, `No items found matching "${search_term}"`);
            // } else {
            //     update_status(d, config, `Found ${total_found} items matching "${search_term}". Showing page 1 of ${d._search_total_pages}`);
            // }
            update_pagination(d, config);
            d.$wrapper.find(`#${config.clear_btn_id}`).show();
        });
    }).catch(error => {
        console.error("Error searching items:", error);
        update_items_container(d, config, [], `Error searching for "${search_term}"`);
        update_status(d, config, `Error searching for "${search_term}"`);
    });
}

// Reset to show all items
function reset_to_all_items(d, config) {
    if (d._searchTimeout) {
        clearTimeout(d._searchTimeout);
    }
    
    d._is_searching = false;
    d._search_term = '';
    d._current_page = 1;
    load_page(d, config, 1);
    d.$wrapper.find(`#${config.clear_btn_id}`).hide();
}

// Update status message
function update_status(d, config, message) {
    let status_element = d.$wrapper.find(`#${config.status_id}`);
    if (status_element.length) {
        status_element.text(message);
    }
}

// Generic container update function
function update_items_container(d, config, items, empty_message = null) {
    let container = d.$wrapper.find(`#${config.container_id}`);
    
    if (items.length === 0) {
        container.html(`
            <div class="text-center" style="padding: 40px; color: #888;">
                <i class="fa fa-inbox" style="font-size: 48px; margin-bottom: 10px;"></i>
                <div>${empty_message || "No items found"}</div>
            </div>
        `);
        return;
    }

    let html = `<table class="table table-hover" style="margin: 0;">
        <thead style="position: sticky; top: 0; background: white; z-index: 10; box-shadow: 0 2px 2px rgba(0,0,0,0.1);">
            <tr>
                <th style="width: 5%; padding: 12px 8px; border-right: 1px solid #ededed;">Select</th>`;
    
    config.columns.forEach(col => {
        html += `<th style="width: ${col.width}; padding: 12px 8px; border-right: 1px solid #ededed;">${col.label}</th>`;
    });
    
    html += `</tr></thead><tbody>`;

    items.forEach((item, index) => {
        html += `<tr class="item-row" style="cursor: pointer;" data-index="${index}">
            <td style="padding-left: 20px; padding-top: 14px; border-right: 1px solid #ededed;">
                <input type="radio" name="item_radio" value="${index}" style="transform: scale(1.2); margin: 0;">
            </td>`;
        
        config.columns.forEach(col => {
            let value = item[col.field] || '';
            if (col.format === 'date' && value) {
                value = frappe.datetime.str_to_user(value);
            }
            if (col.field === 'item_group') {
                value = `<span class="label label-default">${value}</span>`;
            } else if (col.field === 'name' || col.field === 'item_code') {
                value = `<strong>${value}</strong>`;
            }
            html += `<td style="padding: 10px 8px; border-right: 1px solid #ededed;">${value}</td>`;
        });
        
        html += `</tr>`;
    });

    html += `</tbody></table>`;
    container.html(html);

    // Setup event handlers
    container.find('input[name="item_radio"]').on('change', function() {
        let index = parseInt($(this).val());
        d._selected_item = items[index];
    });

    container.find('.item-row').on('click', function() {
        let index = $(this).data('index');
        let radio = $(this).find('input[type="radio"]');
        radio.prop('checked', true).trigger('change');
    });
}

// Generic pagination function
function update_pagination(d, config) {
    let container = d.$wrapper.find(`#${config.pagination_id}`);
    
    let total_pages = d._is_searching ? d._search_total_pages : d._total_pages;
    let current_page = d._current_page;
    
    if (total_pages <= 1) {
        container.html('');
        return;
    }
    
    let html = '<nav><ul class="pagination pagination-sm" style="margin: 0; justify-content: center;">';
    
    // Previous button
    if (current_page > 1) {
        html += `<li><a href="#" class="page-btn" data-page="${current_page - 1}">« Previous</a></li>`;
    } else {
        html += `<li class="disabled"><span>« Previous</span></li>`;
    }
    
    // Page numbers
    let start_page = Math.max(1, current_page - 3);
    let end_page = Math.min(total_pages, current_page + 3);
    
    if (start_page > 1) {
        html += `<li><a href="#" class="page-btn" data-page="1">1</a></li>`;
        if (start_page > 2) {
            html += `<li class="disabled"><span>...</span></li>`;
        }
    }
    
    for (let i = start_page; i <= end_page; i++) {
        if (i === current_page) {
            html += `<li class="active"><span>${i}</span></li>`;
        } else {
            html += `<li><a href="#" class="page-btn" data-page="${i}">${i}</a></li>`;
        }
    }
    
    if (end_page < total_pages) {
        if (end_page < total_pages - 1) {
            html += `<li class="disabled"><span>...</span></li>`;
        }
        html += `<li><a href="#" class="page-btn" data-page="${total_pages}">${total_pages}</a></li>`;
    }
    
    // Next button
    if (current_page < total_pages) {
        html += `<li><a href="#" class="page-btn" data-page="${current_page + 1}">Next »</a></li>`;
    } else {
        html += `<li class="disabled"><span>Next »</span></li>`;
    }
    
    html += '</ul></nav>';
    
    // Jump to page
    html += `<div style="margin-top: 10px;">
                <small>Jump to page: 
                    <input type="number" class="jump-page" min="1" max="${total_pages}" 
                           style="width: 60px; padding: 2px; text-align: center;" 
                           placeholder="${current_page}">
                    <button class="btn btn-xs btn-default jump-btn">Go</button>
                </small>
             </div>`;
    
    container.html(html);
    
    // Setup pagination event handlers
    container.find('.page-btn').on('click', function(e) {
        e.preventDefault();
        let page = parseInt($(this).data('page'));
        if (d._is_searching) {
            load_search_page(d, config, page);
        } else {
            load_page(d, config, page);
        }
    });
    
    container.find('.jump-btn').on('click', function() {
        let page = parseInt(container.find('.jump-page').val());
        if (page && page >= 1 && page <= total_pages) {
            if (d._is_searching) {
                load_search_page(d, config, page);
            } else {
                load_page(d, config, page);
            }
        }
    });
    
    container.find('.jump-page').on('keypress', function(e) {
        if (e.which === 13) {
            container.find('.jump-btn').click();
        }
    });
}

// Load search results page
function load_search_page(d, config, page_number) {
    d._current_page = page_number;
    let start = (page_number - 1) * d._items_per_page;
    
    update_status(d, config, `Loading search results page ${page_number}...`);
    
    let or_filters = [
        ["name", "like", `%${d._search_term}%`],
        ["item_code", "like", `%${d._search_term}%`],
        ["item_name", "like", `%${d._search_term}%`]
    ];
    
    if (config.doctype === "Stone Request") {
        or_filters.push(["material_id", "like", `%${d._search_term}%`]);
    } else {
        or_filters.push(["custom_material_id", "like", `%${d._search_term}%`]);
    }
    
    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: config.doctype,
            filters: config.filters,
            or_filters: or_filters,
            fields: config.db_fields,
            limit_start: start,
            limit_page_length: d._items_per_page,
            order_by: config.doctype === "Stone Request" ? "creation desc" : "item_code"
        }
    }).then(r => {
        let items = r.message || [];
        update_items_container(d, config, items);
        
        update_status(d, config, `Found ${d._search_total_items} items matching "${d._search_term}". Showing page ${page_number} of ${d._search_total_pages}`);
        update_pagination(d, config);
    }).catch(error => {
        console.error("Error loading search page:", error);
        update_items_container(d, config, [], `Error loading search page ${page_number}`);
    });
}

// Handle primary action based on dialog type
async function handle_primary_action(frm, d, config) {
    let selected_item = d._selected_item;
    if (!selected_item) {
        frappe.msgprint("Please select an item first.");
        return;
    }

    if (config.doctype === "Stone Request") {
        await populate_item_fields_from_stone_request(frm, selected_item);
        frm.set_value('required_pieces', selected_item.required_piece || 0);
        frappe.show_alert({
            message: `Stone Request ${selected_item.name} inserted successfully`,
            indicator: 'green'
        });
    } else {
        // Handle Item selection
        frm.set_value("item_code", selected_item.item_code);
        frm.set_value("item_name", selected_item.item_name);
        frm.set_value("material_id", selected_item.custom_material_id);
        frappe.show_alert({
            message: `Item ${selected_item.item_code} inserted successfully`,
            indicator: 'green'
        });
    }
    d.hide();
}

// Reset dialog data
function reset_dialog_data(d, config) {
    update_items_container(d, config, []);
    frappe.show_alert({
        message: "Search cleared and table reset",
        indicator: 'blue'
    });
}

// Populate form fields from Stone Request
async function populate_item_fields_from_stone_request(frm, selected_item) {
    frm.set_value('sr_id', selected_item.name);
    
    // Get item metadata if needed
    let item_meta = {};
    if (selected_item.item_code && !selected_item.gemstone) {
        try {
            item_meta = await frappe.call({
                method: "frappe.client.get",
                args: { doctype: "Item", name: selected_item.item_code }
            }).then(r => r.message || {});
        } catch (err) {
            console.log("Could not fetch Item meta:", err);
        }
    }

    // Set form fields
    const field_updates = {
        'item_code': selected_item.item_code || '',
        'item_name': selected_item.item_name || '',
        'required_pieces': selected_item.required_piece || 0,
        'requested_carats': selected_item.required_carat || 0,
        'item_group': item_meta.item_group || '',
        'material_id': selected_item.material_id || item_meta.custom_material_id || '',
        'gemstone': selected_item.gemstone || item_meta.custom_gemstone || '',
        'country_of_origin': selected_item.country_of_origin || '',
        'avg_carat_weight': flt(selected_item.avg_carat_weight) || 0,
        'sku_carat_weight': flt(selected_item.sku_carat_weight) || 0,
        'stone_pieces': selected_item.stone_pieces || '',
        'grade': selected_item.grade || '',
        'cut': selected_item.cut || '',
        'setting_type': selected_item.setting_type || '',
        'merch_color__attribute': selected_item.merch_colorattribute || '',
        'stone_treatment_list': selected_item.stone_treatment_list || '',
        'sku_sales_order': selected_item.sku_sales_order || ''
    };

    Object.keys(field_updates).forEach(fieldname => {
        frm.set_value(fieldname, field_updates[fieldname]);
    });

    // Handle Sales Order BOM items
    if (selected_item.sku_sales_order) {
        try {
            const sales_order = await frappe.call({
                method: "frappe.client.get",
                args: {
                    doctype: "Sales Order",
                    name: selected_item.sku_sales_order
                }
            });
            
            if (sales_order.message?.custom_bom_items?.length > 0) {
                const first_matching = sales_order.message.custom_bom_items.find(row => row.custom_sales_order_id);
                if (first_matching) {
                    frm.set_value("stone_sales_order", first_matching.custom_sales_order_id);
                }
            }
        } catch (err) {
            console.log("Error fetching Sales Order:", err);
        }
    }
    
    if (item_meta.image) {
        frm.set_value('sku_image', item_meta.image);
    }
    
    frm.refresh_fields();
}

// Create Stone Confirmation
function create_stone_confirmation(frm) {
    frappe.call({
        method: "frappe.client.insert",
        args: {
        doc: {
                doctype: "Stone Confirmation",
                stone_receipt_id: frm.doc.name,
                item_code: frm.doc.item_code,
                item_name: frm.doc.item_name,
                supplier: frm.doc.supplier,
                pieces_received: frm.doc.pieces_received,
                // accepted_pieces: frm.doc.accepted_pieces,
                // accepted_carat: frm.doc.accepted_carat,
                carat_received: frm.doc.carat_received,
                stone_receipt_type: frm.doc.stone_receipt_type,
