// Stone Request fulfillment functions
async function update_stone_request_fulfillment_after_save(frm) {
    try {
        if (!frm.doc.sr_id) return;
        
        let required_pieces_value = flt(frm.doc.required_pieces) || 0;
        
        let sr_doc = await frappe.call({
            method: "frappe.client.get",
            args: { doctype: "Stone Request", name: frm.doc.sr_id }
        });

        if (!sr_doc.message) return;

        let stone_request = sr_doc.message;
        stone_request.stone_receipt_id = frm.doc.name;
        
        if (!stone_request.stone_request_fulfillment) {
            stone_request.stone_request_fulfillment = [];
        }
        
        let existing_fulfillment = stone_request.stone_request_fulfillment.find(
            row => row.stone_receipt_id === frm.doc.name
        );
        
        if (!existing_fulfillment) {
            stone_request.stone_request_fulfillment.push({
                stone_receipt_id: frm.doc.name,
                received_piece: required_pieces_value,
                doctype: "Stone Request Fulfillment"
            });
        } else {
            existing_fulfillment.received_piece = required_pieces_value;
        }
        
        await frappe.call({
            method: "frappe.client.save",
            args: { doc: stone_request }
        });
        
        frappe.show_alert({
            message: __("Stone Request updated with fulfillment entry"),
            indicator: 'green'
        });
        
    } catch (err) {
        console.error("Error in update_stone_request_fulfillment_after_save:", err);
        frappe.msgprint({
            title: __("Error"),
            message: __("Error updating Stone Request fulfillment: {0}", [err.message || err]),
            indicator: 'red'
        });
    }
}

async function update_stone_request_receipt_id(frm) {
    try {
        if (!frm.doc.sr_id) return;
        
        let sr_doc = await frappe.call({
            method: "frappe.client.get",
            args: { doctype: "Stone Request", name: frm.doc.sr_id }
        }).then(r => r.message);

        if (!sr_doc) return;

        if (sr_doc.item_code && sr_doc.item_code === frm.doc.item_code) {
            sr_doc.stone_receipt_id = frm.doc.name;
            
            if (!sr_doc.stone_request_fulfillment) {
                sr_doc.stone_request_fulfillment = [];
            }
            
            let existing_entry = sr_doc.stone_request_fulfillment.find(
                row => row.stone_receipt_id === frm.doc.name
            );
            
            if (!existing_entry) {
                sr_doc.stone_request_fulfillment.push({
                    stone_receipt_id: frm.doc.name,
                    received_pieces: flt(frm.doc.required_pieces) || 0,
                    doctype: "Stone Request Fulfillment" 
                });
            } else {
                existing_entry.received_pieces = flt(frm.doc.required_pieces) || 0;
            }
            
            await frappe.call({
                method: "frappe.client.save",
                args: { doc: sr_doc }
            });
            
            frappe.show_alert({
                message: __("Stone Request updated with Receipt ID and Fulfillment"),
                indicator: 'green'
            });
        }
        
    } catch (err) {
        console.error("Error updating Stone Request:", err);
        frappe.msgprint("Error updating Stone Request with Receipt ID and Fulfillment");
    }
}

