async function set_stores_warehouse(frm) {
    if (!frm.doc.company) {
        frm.set_value('set_warehouse', '');
        return;
    }

    const res = await frappe.db.get_value('Company', frm.doc.company, 'abbr');
    const abbr = res?.message?.abbr;
    if (!abbr) return;

    const warehouse_name = `Stores - ${abbr}`;

    const exists = await frappe.db.exists('Warehouse', warehouse_name);
    if (!exists) {
        frappe.msgprint(`Warehouse "${warehouse_name}" not found. Please create it.`);
        return;
    }

    frm.set_value('set_warehouse', warehouse_name);
}

async function update_summary_fields(dialog) {
    const selected = dialog.fields_dict.items_table.grid.get_selected_children();

    let total_requested_qty = 0;
    let total_selected_qty = 0;
    let total_stock_qty = 0;

    let seen_items = new Set();

    for (let row of selected) {
        total_requested_qty += flt(row.qty || 0);
        total_selected_qty += flt(row.selected_qty || 0);


        if (row.item_code && !seen_items.has(row.item_code)) {
            let stock_qty = await get_total_stock_qty(row.item_code);
            total_stock_qty += stock_qty;
            seen_items.add(row.item_code);
        }
    }

    dialog.set_value("requested_qty", total_requested_qty);
    dialog.set_value("selected_qty", total_selected_qty);
    dialog.set_value("stock_qty", total_stock_qty);
}

async function get_total_stock_qty(item_code) {
    try {
        const response = await frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Bin",
                filters: {
                    item_code: item_code
                },
                fields: ["actual_qty"]
            }
        });

        const bins = response.message || [];
        const total = bins.reduce((sum, bin) => sum + flt(bin.actual_qty || 0), 0);
        return total;
    } catch (e) {
        console.error("Failed to fetch stock for", item_code, e);
        return 0;
    }
}


function toggleDialogTables(dialog, showItems) {
    let requests_table = dialog.get_field('requests_table');
    let items_table = dialog.get_field('items_table');
    let search_field = dialog.get_field('search_items');
    let consolidate_field = dialog.get_field('consolidate_items');
    
    requests_table.df.hidden = showItems;
    requests_table.refresh();
    
    items_table.df.hidden = !showItems;
    items_table.refresh();
    
    search_field.df.hidden = !showItems;
    search_field.refresh();
    
    consolidate_field.df.hidden = !showItems;
    consolidate_field.refresh();
    
    dialog.refresh();
}

function consolidateItems(items) {
    let grouped = {};
    
    items.forEach(item => {
        let key = `${item.item_code || ''}-${item.item_name || ''}`;
        
        if (!grouped[key]) {
            grouped[key] = {
                ...item,
                stone_request: [item.stone_request],
                qty: flt(item.qty) || 0,
                _consolidated: true
            };
        } else {
            if (grouped[key].stone_request.indexOf(item.stone_request) === -1) {
                grouped[key].stone_request.push(item.stone_request);
            }
            grouped[key].qty += flt(item.qty) || 0;
        }
    });
    
    return Object.values(grouped).map(item => ({
        ...item,
        stone_request: item.stone_request.join(', ')
    }));
}

function applyTableFilters(dialog, searchTerm, shouldConsolidate) {
    if (!dialog._original_items_data) return;

    let filtered_items = dialog._original_items_data;

    if (searchTerm && searchTerm.trim() !== '') {
        searchTerm = searchTerm.toLowerCase().trim();
        let keywords = searchTerm.split(/\s+/).filter(keyword => keyword.length > 0);
        
        filtered_items = filtered_items.filter(item => {
            let searchableText = [
                item.item_code || '',
                item.item_name || '',
                item.stone_request || ''
            ].join(' ').toLowerCase();
            
            return keywords.some(keyword => searchableText.includes(keyword));
        });
    }
    
    if (shouldConsolidate) {
        filtered_items = consolidateItems(filtered_items);
    }

    let items_table = dialog.get_field('items_table');
    items_table.df.data = filtered_items;
    items_table.refresh();
}

async function loadStoneRequestItems(dialog, stone_requests) {
    let all_items = [];
    for (let req of stone_requests) {
        let doc = await frappe.call({
            method: "frappe.client.get",
            args: { doctype: "Stone Request", name: req.name }
        }).then(r => r.message);

        if (doc?.stone_request_items?.length) {
            let available_items = doc.stone_request_items;  
            
            all_items.push(...available_items.map(item => ({
                item_code: item.item_code,
                item_name: item.item_name,
                qty: item.qty,
                stone_request: req.name,
                parent: req.name 
            })));
        }
    }

    dialog._original_items_data = all_items;

    let items_table = dialog.get_field('items_table');
    items_table.df.data = all_items;
    items_table.refresh();
}

