async function populateItemFields(frm, selected_item) {
    frm.doc.items = frm.doc.items.filter(row => row.item_code);
    frm.refresh_field("items");

    const item = selected_item._full_item_data || selected_item;

    let final_qty = flt(item.selected_qty) > 0 
        ? flt(item.selected_qty) 
        : flt(item.qty);

    let company_abbr = '';
    if (frm.doc.company) {
        const company_info = await frappe.db.get_value('Company', frm.doc.company, 'abbr');
        company_abbr = company_info?.message?.abbr || '';
    }

    let required_by = '';
    let requested_company = '';
    if (item.parent) {
        const parent_doc = await frappe.db.get_value('Stone Request', item.parent, ['required_by', 'requested_company']);
        required_by = parent_doc.message.required_by || '';
        requested_company = parent_doc.message.requested_company || '';
    }
    
    frm.add_child("items", {
        item_code: item.item_code,
        item_name: item.item_name,
        qty: final_qty,
        rate: 1,
        amount: 1,
        uom: item.uom || 'Carat',
        income_account: company_abbr ? `Sales - ${company_abbr}` : '',
        due_date: required_by
    });

    if (required_by) frm.set_value('due_date', required_by);
    if (company_abbr) frm.set_value('debit_to', `Debtors - ${company_abbr}`);
    if (requested_company) frm.set_value('customer', requested_company);

    frm.refresh_field("items");
}


async function populateFromStoneRequest(frm, selected_request) {

    frm.doc.items = frm.doc.items.filter(row => row.item_code);
    frm.refresh_field("items");

    let doc = await frappe.call({
        method: "frappe.client.get",
        args: { doctype: "Stone Request", name: selected_request.name }
    }).then(r => r.message);

    if (!doc?.stone_request_items?.length) {
        frappe.msgprint("No items found in selected Stone Request.");
        return;
    }

    doc.stone_request_items.forEach(item => {
        let final_qty = item.selected_qty && flt(item.selected_qty) > 0 
            ? flt(item.selected_qty) 
            : flt(item.qty);

        frm.add_child("items", {
            item_code: item.item_code,
            item_name: item.item_name,
            qty: final_qty,
            rate:1,
            amount:1,
            uom:item.uom || 'Carat'
        });
    });

    frm.refresh_field("items");
}

