                                { fieldtype: "Currency", fieldname: "grand_total", label: "Total", in_list_view: 1, read_only: 1 }
                            ]
                        }
                    ]
                });

                
                function filter_table() {
                    const name_filter = (dialog.get_value('name_filter') || '').trim().toLowerCase();
                    const customer_filter = (dialog.get_value('supplier_filter') || '').trim().toLowerCase();
                
                    const filtered_data = original_data.filter(row => {
                        const name = (row.name || '').toLowerCase();
                        const customer = (row.customer || '').toLowerCase();
                        return name.includes(name_filter) && customer.includes(customer_filter);
                    });
                
                    dialog.fields_dict.sales_invoices.df.data = filtered_data;
                    dialog.fields_dict.sales_invoices.refresh();
                }

                function debounce(func, delay) {
                    let timeout;
                    return function (...args) {
                        clearTimeout(timeout);
                        timeout = setTimeout(() => func.apply(this, args), delay);
                    };
                }

                dialog.show();

                const debouncedFilter = debounce(filter_table, 300);

                $(dialog.fields_dict.name_filter.$wrapper).find('input').on('input', debouncedFilter);
                $(dialog.fields_dict.supplier_filter.$wrapper).find('input').on('input', debouncedFilter);
            });
