async function set_store_warehouse(frm) {
    if (!frm.doc.company) {
        frm.set_value('set_warehouse', '');
        return;
    }

    const res = await frappe.db.get_value('Company', frm.doc.company, 'abbr');
    const abbr = res?.message?.abbr;

    if (!abbr) return;

    const warehouse_name = `Stores - ${abbr}`;
    frm.set_value('set_warehouse', warehouse_name);
}


function insert_items_to_invoice(frm, items, dialog, hadErrors = false) {
    if (!items.length) {
        frappe.msgprint(hadErrors ? "Error occurred while fetching items." : "No items found in selected Sales Invoices.");
        return;
    }

    const to_remove = [];
    frm.doc.items.forEach((item, idx) => {
        if (!item.item_code || item.item_code.trim() === '') {
            to_remove.push(idx);
        }
    });

    to_remove.reverse().forEach(idx => {
        frm.doc.items.splice(idx, 1);
    });


    items.forEach(item => {
        frm.add_child("items", {
            item_code: item.item_code,
            item_name: item.item_name,
            description: item.description,
            qty: item.qty,
            stock_qty: item.qty,
            rate: item.rate,
            uom: item.uom,
            amount: item.amount
        });
    });

    frm.refresh_field("items");
    dialog.hide();

    if (hadErrors) {
        frappe.msgprint("Items added successfully (some errors occurred).");
    }
}

frappe.ui.form.on('Stone Confirmation', {
    
    after_save: async function(frm) {
        if (frm.doc.stone_receipt_id) {
            await update_stone_requests_with_confirmation_id(frm);
        }
    },
    update_item_description: function(frm) {
        let parts = [];
        if (frm.doc.item_code) parts.push(`Item Code: ${frm.doc.item_code}`);
        if (frm.doc.item_name) parts.push(`Item Name: ${frm.doc.item_name}`);
        if (frm.doc.material_id) parts.push(`Material ID: ${frm.doc.material_id}`);
        if (frm.doc.merch_color_attribute) parts.push(`Color: ${frm.doc.merch_color_attribute}`);
        if (frm.doc.gemstone) parts.push(`Gemstone: ${frm.doc.gemstone}`);
        if (frm.doc.country_of_origin) parts.push(`Country of Origin: ${frm.doc.country_of_origin}`);
        if (frm.doc.setting_type) parts.push(`Setting Type: ${frm.doc.setting_type}`);
        if (frm.doc.avg_carat_weight) parts.push(`Avg Carat Weight: ${frm.doc.avg_carat_weight}`);
        if (frm.doc.sku_carat_weight) parts.push(`SKU Carat Weight: ${frm.doc.sku_carat_weight}`);
        if (frm.doc.cut) parts.push(`Cut: ${frm.doc.cut}`);
        if (frm.doc.grade) parts.push(`Grade: ${frm.doc.grade}`);
        if (frm.doc.stone_pieces) parts.push(`Stone Pieces: ${frm.doc.stone_pieces}`);
        if (frm.doc.merch_color__attribute) parts.push(`Merch Color/Attribute: ${frm.doc.merch_color__attribute}`);
        if (frm.doc.stone_treatment_list) parts.push(`Stone Treatment List: ${frm.doc.stone_treatment_list}`);
        frm.set_value("item_description", parts.join(" | "));
    },
    refresh(frm) {

        frm.add_custom_button('Purchase Invoice', async () => {
            console.log("Custom button clicked");
            console.log("Current form doc:", frm.doc);

            let default_qty = frm.doc.accepted_pieces || frm.doc.pieces_received || 1;
            
            if (frm.doc.stone_receipt_id) {
                try {
                    let sr_doc = await frappe.call({
                        method: "frappe.client.get",
                        args: {
                            doctype: "Stone Receipt",
                            name: frm.doc.stone_receipt_id
                        }
                    }).then(r => r.message);
                    
                    if (sr_doc && sr_doc.required_pieces) {
                        default_qty = sr_doc.required_pieces;
                    }
                } catch (err) {
                    console.log("Could not fetch Stone Receipt required_pieces:", err);
                }
            }

            const d = new frappe.ui.Dialog({
                title: 'Create Purchase Invoice',
                fields: [
                    {
                        label: 'Item Code',
                        fieldname: 'item_code',
                        fieldtype: 'Data',
                        default: frm.doc.item_code,
                        read_only: 1
                    },
                    {
                        label: 'Qty',
                        fieldname: 'qty',
                        fieldtype: 'Float',
                        default: default_qty,
                        reqd: 1
                    },
                    {
                        label: 'Sales Invoice No',
                        fieldname: 'sales_invoice',
                        fieldtype: 'Link',
                        options: 'Sales Invoice'
                    }
                ],
                primary_action_label: 'Create',
                primary_action(values) {
                    console.log("Dialog primary action triggered");
                    console.log("Dialog values qty:", values.qty);
                    console.log("Dialog values item_code:", values.item_code);
                    console.log("Dialog values sales_invoice:", values.sales_invoice);
                    
                    if (!values.qty || values.qty <= 0) {
                        frappe.msgprint(__('Please enter valid quantity'));
                        return;
                    }
                    
                    d.hide();

                    if (values.qty && !frm.doc.pieces_received) {
                        frm.set_value('pieces_received', values.qty);
                        frm.save().then(() => {
                            createPurchaseInvoice(frm, values);
                        });
                    } else {
                        createPurchaseInvoice(frm, values);
                    }
                }
            });
            d.show();
        }, __("Create"));
        calculate_balances(frm);
    },
    validate: function(frm) {
        if (frm.doc.accepted_pieces > frm.doc.pieces_received) {
            frappe.throw(__('Accepted Pieces cannot be greater than Pieces Received'));
        }
        if (frm.doc.accepted_carat > frm.doc.carat_received) {
            frappe.throw(__('Accepted Carat cannot be greater than Carat Received'));
        }
    },
    before_save(frm) {
        frm.trigger("update_item_description");
        if (frm.doc.accepted_pieces === 0) {
            frm.set_value('accepted_pieces', null);
        }
        if (frm.doc.accepted_carat === 0) {
            frm.set_value('accepted_carat', null);
        }
    }
    ,
    accepted_pieces(frm) {
        calculate_balances(frm);
    },

    accepted_carat(frm) {
        calculate_balances(frm);
    },

    pieces_received(frm) {
        calculate_balances(frm);
    },

    carat_received(frm) {
        calculate_balances(frm);
    }
});

function calculate_balances(frm) {
    let pieces_received = frm.doc.pieces_received || 0;
    let accepted_pieces = frm.doc.accepted_pieces || 0;

    let carat_received = frm.doc.carat_received || 0;
    let accepted_carat = frm.doc.accepted_carat || 0;

    frm.set_value('pieces_balance', pieces_received - accepted_pieces);
    frm.set_value('carats_balance', carat_received - accepted_carat);
}

function createPurchaseInvoice(frm, values) {
    console.log("=== createPurchaseInvoice function started ===");
    console.log("frm.doc.supplier:", frm.doc.supplier);
    console.log("frm.doc.item_code:", frm.doc.item_code);
    console.log("values.qty:", values.qty);
    console.log("values.sales_invoice:", values.sales_invoice);
    
    if (!frm.doc.supplier) {
        console.error("Supplier missing");
        frappe.msgprint(__('Supplier is required in Stone Confirmation'));
        return;
    }
    
    if (!values.item_code) {
        console.error("Item code missing");
        frappe.msgprint(__('Item Code is required'));
        return;
    }

    console.log("All validations passed, making API call");

    frappe.call({
        method: "frappe.client.insert",
        args: {
            doc: {
                doctype: "Purchase Invoice",
                supplier: frm.doc.supplier,
                posting_date: frappe.datetime.nowdate(),
                bill_no: values.sales_invoice,
                items: [
                    {
                        item_code: values.item_code,
                        qty: values.qty,
                        rate: 1,
                        custom_stone_confirmation_id: frm.doc.name
                    }
                ],
                references: values.sales_invoice ? [
                    {
                        reference_doctype: "Sales Invoice",
                        reference_name: values.sales_invoice
                    }
                ] : []
            }
        },
        callback: function(r) {
            console.log("=== API Response received ===");
            console.log("r.exc:", r.exc);
            console.log("r.message:", r.message);
            console.log("Full response:", r);
            
            if (!r.exc && r.message) {
                console.log("Success! PI created:", r.message.name);
                frappe.msgprint(__('Purchase Invoice {0} created', [r.message.name]));
                
                 frm.set_value("purchase_invoice_id", r.message.name);
                 frm.save();
                
                frappe.set_route("Form", "Purchase Invoice", r.message.name);
            } else {
                console.error("Error occurred:", r.exc || r.message);
                frappe.msgprint({
                    title: __('Error'),
                    message: __('Error creating Purchase Invoice. Check console for details.'),
                    indicator: 'red'
                });
                
                if (r.exc) {
                    console.error("Detailed error:", r.exc);
                    frappe.msgprint("Error: " + r.exc);
                }
            }
        }
    });
}

async function update_stone_requests_with_confirmation_id(frm) {
    try {
        console.log('Updating Stone Requests with Stone Confirmation ID...');
        
        // First, get the Stone Receipt document
        if (!frm.doc.stone_receipt_id) {
            console.log("No Stone Receipt ID found");
            return;
        }

        let stone_receipt = await frappe.call({
            method: "frappe.client.get",
            args: {
                doctype: "Stone Receipt",
                name: frm.doc.stone_receipt_id
            }
        }).then(r => r.message);

        if (!stone_receipt) {
            console.log(`Stone Receipt ${frm.doc.stone_receipt_id} not found`);
            return;
        }

        // Collect all Stone Request IDs from the child table
        let stone_request_ids = [];
        
        if (stone_receipt.stones_request_fetched && stone_receipt.stones_request_fetched.length > 0) {
            stone_receipt.stones_request_fetched.forEach(row => {
                if (row.stones_request_id) {
                    stone_request_ids.push(row.stones_request_id);
                }
            });
        }

        if (stone_request_ids.length === 0) {
            console.log("No Stone Request IDs found in stones_request_fetched table");
            return;
        }

        console.log('Stone Request IDs to update:', stone_request_ids);

        let updated_count = 0;
        for (let sr_id of stone_request_ids) {
            try {
                let stone_request = await frappe.call({
                    method: "frappe.client.get",
                    args: {
                        doctype: "Stone Request",
                        name: sr_id
                    }
                }).then(r => r.message);

                if (!stone_request) {
                    console.log(`Stone Request ${sr_id} not found`);
                    continue;
                }

                if (!stone_request.stone_request_fulfillment) {
                    stone_request.stone_request_fulfillment = [];
                }

                let existing_fulfillment = stone_request.stone_request_fulfillment.find(
                    row => row.stone_receipt_id === frm.doc.stone_receipt_id
                );

                if (existing_fulfillment) {
                    existing_fulfillment.stone_confirmation_id = frm.doc.name;
                    existing_fulfillment.confirmed_piece = frm.doc.pieces_received || 0;
                    existing_fulfillment.confirmed_carat = frm.doc.carat_received || 0;
                    console.log(`Updated existing fulfillment entry for ${sr_id} with Stone Confirmation ID: ${frm.doc.name}, confirmed_piece: ${frm.doc.pieces_received}, confirmed_carat: ${frm.doc.carat_received}`);
                } else {
                    stone_request.stone_request_fulfillment.push({
                        stone_receipt_id: frm.doc.stone_receipt_id,
                        stone_confirmation_id: frm.doc.name,
                        confirmed_piece: frm.doc.pieces_received || 0,
                        confirmed_carat: frm.doc.carat_received || 0,
                        doctype: "Stone Request Fulfillment"
                    });
                    console.log(`Added new fulfillment entry for ${sr_id} with Stone Confirmation ID: ${frm.doc.name}, confirmed_piece: ${frm.doc.pieces_received}, confirmed_carat: ${frm.doc.carat_received}`);
                }

                await frappe.call({
                    method: "frappe.client.save",
                    args: {
                        doc: stone_request
                    }
                });

                updated_count++;
                console.log(`Stone Request ${sr_id} updated successfully`);

            } catch (err) {
                console.error(`Error updating Stone Request ${sr_id}:`, err);
                frappe.show_alert({
                    message: __("Error updating Stone Request {0}: {1}", [sr_id, err.message || err]),
                    indicator: 'red'
                });
            }
        }

        if (updated_count > 0) {
            frappe.show_alert({
                message: __("{0} Stone Request(s) updated with Stone Confirmation ID", [updated_count]),
                indicator: 'green'
            });
            console.log(`${updated_count} Stone Requests updated successfully with Stone Confirmation ID`);
        }

    } catch (err) {
        console.error("Error in update_stone_requests_with_confirmation_id:", err);
        frappe.msgprint({
            title: __("Error"),
            message: __("Error updating Stone Requests with Confirmation ID: {0}", [err.message || err]),
            indicator: 'red'
        });
    }
}
